'use server'

import { createClient } from '@/utils/supabase/server'
import { revalidatePath } from 'next/cache'

export type Sport = {
  id: string
  name: string
  season: 'Fall' | 'Winter' | 'Spring'
  coach_count: number
  athlete_count: number
}

export type SportDetail = Sport & {
  coaches: { id: string, name: string, role: string, user_id: string }[]
  events: { id: string, title: string, date: string, location: string, notes: string }[]
  roster: { id: string, first_name: string, last_name: string, company: string, rank: string }[]
}

// 1. Get All Sports with Counts
export async function getSportsList(season?: string) {
  const supabase = createClient()
  let query = supabase.from('sports').select('id, name, season, is_active').order('name')
  
  if (season) query = query.eq('season', season)
  
  const { data: sports, error } = await query
  if (error) return []

  // Fix: Map the raw data to satisfy the Sport type by adding default counts
  // (In a future update, you can replace these 0s with actual counts via a new RPC)
  return sports.map((s: any) => ({
      ...s,
      coach_count: 0, 
      athlete_count: 0
  })) as Sport[]
}

// 2. Get Single Sport Details
export async function getSportDetail(sportId: string): Promise<SportDetail | null> {
  const supabase = createClient()
  
  // A. Fetch Metadata
  const { data: sport } = await supabase.from('sports').select('*').eq('id', sportId).single()
  if (!sport) return null

  // B. Fetch Coaches
  const { data: coaches } = await supabase
    .from('sport_coaches')
    .select('id, role, profile:coach_id(id, first_name, last_name)')
    .eq('sport_id', sportId)
  
  // C. Fetch Events
  const { data: events } = await supabase
    .from('sport_events')
    .select('*')
    .eq('sport_id', sportId)
    .order('event_date', { ascending: true })

  // D. Fetch Roster (Dynamic Query on Profile Column)
  const colMap = { 'Fall': 'sport_fall', 'Winter': 'sport_winter', 'Spring': 'sport_spring' }
  const targetCol = colMap[sport.season as keyof typeof colMap]
  
  const { data: roster } = await supabase
    .from('profiles')
    .select('id, first_name, last_name, cadet_rank, company:companies(company_name)')
    .eq(targetCol, sport.name)
    .order('last_name')

  return {
    ...sport,
    coach_count: coaches?.length || 0,
    athlete_count: roster?.length || 0,
    coaches: coaches?.map((c: any) => ({ 
        id: c.id, 
        user_id: c.profile.id,
        name: `${c.profile.last_name}, ${c.profile.first_name}`, 
        role: c.role 
    })) || [],
    events: events?.map((e: any) => ({...e, date: e.event_date})) || [],
    roster: roster?.map((r: any) => ({
        id: r.id, 
        first_name: r.first_name, 
        last_name: r.last_name, 
        rank: r.cadet_rank, 
        company: r.company?.company_name
    })) || []
  }
}

// 3. Actions
export async function joinCoachingStaff(sportId: string) {
    const supabase = createClient()
    const { data: { user } } = await supabase.auth.getUser()
    if (!user) return { error: 'Unauthorized' }

    const { error } = await supabase.from('sport_coaches').insert({
        sport_id: sportId,
        coach_id: user.id
    })
    
    if (!error) revalidatePath(`/sports/${sportId}`)
    return { error: error?.message }
}

export async function addEvent(sportId: string, event: any) {
    const supabase = createClient()
    const { error } = await supabase.from('sport_events').insert({
        sport_id: sportId,
        title: event.title,
        event_date: event.date,
        location: event.location
    })
    if (!error) revalidatePath(`/sports/${sportId}`)
    return { error: error?.message }
}

export async function addToRoster(cadetId: string, sportName: string, season: string) {
    const supabase = createClient()
    
    const colMap = { 'Fall': 'sport_fall', 'Winter': 'sport_winter', 'Spring': 'sport_spring' }
    const targetCol = colMap[season as keyof typeof colMap]
    
    // Update the profile directly
    const { error } = await supabase
        .from('profiles')
        .update({ [targetCol]: sportName })
        .eq('id', cadetId)

    if (!error) revalidatePath(`/sports`) 
    return { error: error?.message }
}

export async function getUnassignedCadets(season: string) {
    const supabase = createClient()
    const colMap = { 'Fall': 'sport_fall', 'Winter': 'sport_winter', 'Spring': 'sport_spring' }
    const targetCol = colMap[season as keyof typeof colMap]

    // Fetch cadets where sport is null or 'None'
    // Uses an inner join on roles to strictly filter for Role Level < 50 (Students)
    const { data } = await supabase
        .from('profiles')
        .select('id, first_name, last_name, cadet_rank, company:companies(company_name), role:roles!inner(default_role_level)')
        .or(`${targetCol}.is.null,${targetCol}.eq.None`)
        .lt('role.default_role_level', 50)
        .order('last_name')
    
    return data || []
}